import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import 'package:go_router/go_router.dart'; import '../../providers/video_providers.dart';
class HomeScreen extends ConsumerWidget { const HomeScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref) { final videos = ref.watch(featuredProvider); return Scaffold(appBar: AppBar(title: const Text('Padhle')), body: videos.when(loading: () => const Center(child: CircularProgressIndicator()), error: (e, _) => Center(child: Text('Could not load videos: $e')), data: (items) => RefreshIndicator(onRefresh: () async => ref.invalidate(featuredProvider), child: ListView.builder(itemCount: items.length, itemBuilder: (_, i) { final v = items[i]; return ListTile(leading: v.thumbnail == null ? const Icon(Icons.play_circle) : Image.network(v.thumbnail!, width: 100, fit: BoxFit.cover), title: Text(v.title), subtitle: Text(v.description ?? ''), onTap: () => context.push('/video/${v.id}'); }))); } }
